// Browser stand-in for Node built-ins used by kordoc (generated by scripts/gen-node-shims.mjs).
// Functions kordoc only needs on a file system (CLI, OCR, native image tools) throw when called.
import pako from "pako";
const fail=(n)=>()=>{throw new Error(n+" is not available in the browser")};
export const constants={};
export const deflateRawSync=(b,o)=>pako.deflateRaw(b,o);
export const deflateSync=(b,o)=>pako.deflate(b,o);
export const inflateRawSync=(b)=>pako.inflateRaw(b);
export const inflateSync=(b)=>pako.inflate(b);
export default {constants,deflateRawSync,deflateSync,inflateRawSync,inflateSync};
